#include <stdio.h>

void swap_values(int x, int y) {
    int t = x;
    x = y;
    y = t;
}

void swap_pointers(int *x, int *y) {
    int t = *x;
    *x = *y;
    *y = t;
}

int main(void) {
    int a = 1, b = 2;
    swap_values(a, b);
    printf("after swap_values:   a=%d b=%d\n", a, b);
    swap_pointers(&a, &b);
    printf("after swap_pointers: a=%d b=%d\n", a, b);
    return 0;
}
